"use client";

import React from 'react';
import {
    BarChart3,
    TrendingUp,
    Users,
    Scissors,
    DollarSign,
    Calendar,
    ArrowUpRight,
    ArrowDownRight,
    PieChart,
    Download,
    ChevronDown,
    Zap
} from 'lucide-react';
import { Button } from '@/components/ui/Button';

export default function BarberReports() {
    return (
        <div className="max-w-6xl mx-auto space-y-10 animate-fade-in-up">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-white/5">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight mb-1">Meus <span className="text-[var(--color-primary-gold)]">Relatórios</span></h1>
                    <p className="text-gray-500 text-sm italic">Análise de performance e crescimento profissional.</p>
                </div>
                <div className="flex items-center gap-3">
                    <Button variant="outline" className="h-12 px-5 rounded-2xl border-white/5 bg-black/40 text-[10px] font-black uppercase tracking-[0.2em] gap-2">
                        <Calendar className="w-4 h-4" /> ÚLTIMOS 30 DIAS <ChevronDown size={14} />
                    </Button>
                    <Button variant="outline" className="h-12 w-12 p-0 rounded-2xl border-white/5 bg-black/40 flex items-center justify-center hover:border-[var(--color-primary-gold)]/50 transition-colors">
                        <Download size={20} className="text-gray-500" />
                    </Button>
                </div>
            </header>

            {/* Performance Stats Overlay */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {[
                    { label: 'Total Clientes', value: '142', trend: '+12%', icon: <Users size={20} />, color: 'emerald' },
                    { label: 'Ticket Médio', value: 'R$ 68', trend: '+5%', icon: <DollarSign size={20} />, color: 'blue' },
                    { label: 'Serviços/Dia', value: '8.4', trend: '-2%', icon: <Scissors size={20} />, color: 'amber' },
                    { label: 'Conversão', value: '92%', trend: '+8%', icon: <Zap size={20} />, color: 'purple' },
                ].map((stat, i) => (
                    <div key={i} className="bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] p-8 rounded-[2rem] shadow-xl space-y-3 relative overflow-hidden group hover:border-white/10 transition-all">
                        <div className="flex items-center justify-between">
                            <div className={`p-3 rounded-xl bg-white/5 text-gray-500 group-hover:text-white transition-colors`}>{stat.icon}</div>
                            <span className={`text-[10px] font-black flex items-center gap-1 ${stat.trend.startsWith('+') ? 'text-emerald-500' : 'text-red-500'}`}>
                                {stat.trend.startsWith('+') ? <ArrowUpRight size={10} /> : <ArrowDownRight size={10} />} {stat.trend}
                            </span>
                        </div>
                        <div>
                            <p className="text-[9px] text-gray-600 font-bold uppercase tracking-widest">{stat.label}</p>
                            <h3 className="text-2xl font-black text-white">{stat.value}</h3>
                        </div>
                    </div>
                ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Ranking de Serviços */}
                <div className="bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-[3rem] p-10 shadow-2xl space-y-8 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-48 h-48 bg-[var(--color-primary-gold)]/5 rounded-full blur-[60px] -mr-24 -mt-24" />
                    <h3 className="text-xl font-bold flex items-center gap-3 italic relative z-10">
                        <PieChart className="w-5 h-5 text-[var(--color-primary-gold)]" /> Ranking de Serviços
                    </h3>

                    <div className="space-y-6 relative z-10">
                        {[
                            { name: 'Corte Degradê', percentage: 45, count: 64, color: 'var(--color-primary-gold)' },
                            { name: 'Combo Premium', percentage: 25, count: 35, color: '#3b82f6' },
                            { name: 'Barba Terapêutica', percentage: 20, count: 28, color: '#10b981' },
                            { name: 'Corte Social', percentage: 10, count: 14, color: '#6b7280' },
                        ].map((s, i) => (
                            <div key={i} className="space-y-2">
                                <div className="flex items-center justify-between text-[10px] font-black uppercase tracking-widest">
                                    <span className="text-white">{s.name}</span>
                                    <span className="text-gray-500">{s.count} serv. — {s.percentage}%</span>
                                </div>
                                <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
                                    <div
                                        className="h-full rounded-full transition-all duration-1000 ease-out"
                                        style={{ width: `${s.percentage}%`, backgroundColor: s.color }}
                                    />
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="pt-6 border-t border-white/5 flex items-center justify-between relative z-10">
                        <p className="text-[10px] text-gray-600 font-bold uppercase tracking-tighter">Sugestão: Promova o serviço de Pigmentação, ele teve queda de 15%.</p>
                    </div>
                </div>

                {/* Cliente Favorito / Destaque */}
                <div className="bg-gradient-to-br from-black to-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-[3rem] p-10 shadow-2xl space-y-8 flex flex-col justify-between">
                    <div className="space-y-6">
                        <h3 className="text-xl font-bold flex items-center gap-3 italic">
                            <TrendingUp className="w-5 h-5 text-emerald-500" /> Melhores Clientes
                        </h3>

                        <div className="space-y-4">
                            {[
                                { name: 'Gustavo Lima', visits: 12, total: 'R$ 720', photo: 'https://i.pravatar.cc/100?u=1' },
                                { name: 'Rafael Mendes', visits: 9, total: 'R$ 540', photo: 'https://i.pravatar.cc/100?u=2' },
                                { name: 'João Pedro', visits: 7, total: 'R$ 480', photo: 'https://i.pravatar.cc/100?u=3' },
                            ].map((c, i) => (
                                <div key={i} className="flex items-center justify-between p-5 bg-white/[0.02] border border-white/5 rounded-2xl hover:bg-white/5 transition-colors group">
                                    <div className="flex items-center gap-4">
                                        <img src={c.photo} alt="" className="w-12 h-12 rounded-xl grayscale group-hover:grayscale-0 transition-all border border-white/10" />
                                        <div>
                                            <p className="font-bold text-white tracking-tight">{c.name}</p>
                                            <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest leading-none mt-1">{c.visits} Visitas no ano</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-sm font-black text-[var(--color-primary-gold)]">{c.total}</p>
                                        <p className="text-[9px] text-gray-700 font-black uppercase tracking-tighter">Total Gasto</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    <Button variant="outline" className="w-full h-14 rounded-2xl border-white/10 text-gray-500 hover:text-white hover:border-[var(--color-primary-gold)]/50 uppercase text-[10px] font-black tracking-widest border-dashed">
                        RELATÓRIO DE FIDELIDADE COMPLETO
                    </Button>
                </div>
            </div>

            {/* Faturamento Semanal Chart Representation */}
            <div className="bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-[3rem] p-10 md:p-14 shadow-2xl">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
                    <div>
                        <h3 className="text-2xl font-black text-white italic tracking-tight">Evolução de Faturamento</h3>
                        <p className="text-xs text-gray-500 mt-1 uppercase font-bold tracking-widest">Comparativo Diário (Últimos 7 dias)</p>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-[var(--color-primary-gold)]" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-gray-600 italic">Sua Comissão</span>
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-7 gap-4 md:gap-8 h-64 items-end">
                    {[
                        { day: 'SEG', val: 40, active: false },
                        { day: 'TER', val: 65, active: false },
                        { day: 'QUA', val: 55, active: false },
                        { day: 'QUI', val: 85, active: false },
                        { day: 'SEX', val: 95, active: true },
                        { day: 'SÁB', val: 100, active: false },
                        { day: 'DOM', val: 0, active: false },
                    ].map((d, i) => (
                        <div key={i} className="flex flex-col items-center gap-4 h-full relative group">
                            <div className="flex-1 w-full bg-white/5 rounded-t-2xl relative overflow-hidden min-h-[4px]">
                                <div
                                    className={`absolute bottom-0 left-0 w-full transition-all duration-1000 ease-out group-hover:brightness-125 rounded-t-2xl ${d.active ? 'bg-[var(--color-primary-gold)] shadow-[0_0_20px_rgba(212,175,55,0.4)]' : 'bg-gray-800 opacity-40'}`}
                                    style={{ height: `${d.val}%` }}
                                />
                                {d.val > 0 && (
                                    <div className="absolute top-0 left-0 w-full h-full opacity-0 group-hover:opacity-10 transition-opacity bg-white pointer-events-none" />
                                )}
                            </div>
                            <span className={`text-[10px] font-black uppercase tracking-widest ${d.active ? 'text-white' : 'text-gray-700'}`}>{d.day}</span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}
